CREATE TEMPORARY VIEW traffic_cs_explode_${grass_region_without_quote} AS
SELECT
    timp.userid AS user_id
    ,timp.event_id AS event_id
    ,timp.session_id AS session_id
    ,timp.shop_id AS shop_id
    ,timp.deviceid AS device_id
    ,timp.platform AS platform
    ,timp.page_type AS page_type
    ,timp.page_section AS page_section
    ,timp.target_type AS target_type
    ,GET_JSON_OBJECT(timp.data, '$.layout_id') AS layout_id
    ,GET_JSON_OBJECT(timp.data, '$.location') AS location
    ,GET_JSON_OBJECT(timp.data, '$.user_input') AS user_input
    ,CASE 
        WHEN e.elems IS NOT NULL THEN TRIM(LOWER(GET_JSON_OBJECT(e.elems, '$.url')))
        ELSE TRIM(LOWER(GET_JSON_OBJECT(timp.data, '$.url')))
    END AS url
    ,CASE
        WHEN e.elems IS NOT NULL THEN GET_JSON_OBJECT(e.elems, '$.position')
        ELSE GET_JSON_OBJECT(timp.data, '$.position')
    END AS position
    ,GET_JSON_OBJECT(timp.data, '$.search_FE.layout_id') AS fe_layout_id
    ,GET_JSON_OBJECT(timp.data, '$.search_FE.location') AS fe_location
    ,GET_JSON_OBJECT(timp.data, '$.search_FE.user_input') AS fe_user_input
    ,TRIM(LOWER(GET_JSON_OBJECT(timp.data, '$.search_FE.url'))) AS fe_url
    ,TRIM(LOWER(GET_JSON_OBJECT(timp.data, '$.search_FE.position'))) AS fe_position
    ,REPLACE(TRIM(LOWER(GET_JSON_OBJECT(timp.data, '$.search_params.keyword'))), '-', ' ') AS keyword
    ,REPLACE(TRIM(LOWER(GET_JSON_OBJECT(timp.data, '$.search_FE.keyword'))), '-', ' ') AS fe_keyword
    ,timp.log_timestamp
    ,e.elems
FROM
    traffic.shopee_traffic_dwd_impression_hi__reg_s1_live timp
LATERAL VIEW OUTER
    EXPLODE(CAST(from_json(GET_JSON_OBJECT(timp.data, '$.cs_list'), 'array<string>') AS array<string>)) e as elems
WHERE 
    timp.local_date = ${local_date}
    AND timp.grass_region = ${grass_region}
    AND (timp.page_type = 'search' OR (page_type = 'search_suggest_page' AND page_section[0] = 'search_bar'))
    AND timp.target_type = 'curated_search';

